diff --git a/src/type1/t1parse.c b/src/type1/t1parse.c
index 6947b3d..d6083d2 100644
--- a/src/type1/t1parse.c
+++ b/src/type1/t1parse.c
@@ -273,6 +273,7 @@
       FT_UShort  tag;
       FT_Byte*   priv_dict = NULL;
       FT_ULong   priv_len  = 0;
+      FT_Bool    merged    = 0;


       for (;;)
@@ -284,10 +285,13 @@
         if ( tag != 0x8002U )
           break;

-        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + size ) ||
-             FT_STREAM_READ( priv_dict + priv_len, size )        )
+        if ( FT_QREALLOC( priv_dict, priv_len,
+                         priv_len + size + ( priv_len != 0 ) ) ||
+             FT_STREAM_READ( priv_dict + priv_len, size ) )
           goto Fail;

+        if ( priv_len )
+          merged = 1;
         priv_len += size;
       }

@@ -300,6 +304,9 @@
         goto Fail;
       }

+      if ( merged )
+        priv_dict[priv_len] = '\0';
+
       parser->private_dict = priv_dict;
       parser->private_len  = priv_len;
     }

